/* tokens.css — design tokens: fonts, neutral/vertical/dark theme variables */

/* ============================================================
   Aircove Customer Portal — styles.css
   Design tokens + component styles. Visual source of truth.
   Componentized: each block below maps 1:1 to a component the
   Codex team will implement (see manifest.json / README.md).

   THEMING is fully declarative:
     <html data-theme="hvac|snow|lawn|pool|roofing|pest|health|beauty"
           data-mode="light|dark">
   app.js only flips these two attributes — every color derives
   from the custom properties defined here.
   ============================================================ */
/* ---------- Fonts ---------- */
@font-face { font-family: "ManropeFallback"; src: local("Manrope"); }

/* ---------- Design tokens : NEUTRALS (light default) ---------- */
:root {
  --font: "Manrope", system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, "SF Mono", Menlo, monospace;

  --ink:      #1d1d1f;
  --ink-2:    #56607a;
  --ink-3:    #9aa0ad;
  --surface:  #ffffff;
  --surface-2:#f5f5f7;
  --base:     #eef1f6;

  /* rgb triplets used inside rgba() */
  --glass:    255,255,255;   /* frosted-panel fill  */
  --hair:     0,0,0;         /* hairline / shadow    */

  --glass-border: rgba(255,255,255,.70);
  --glass-blur:   blur(24px) saturate(180%);
  --shadow-card:  0 8px 28px rgba(13,38,76,.10), inset 0 1px 0 rgba(255,255,255,.70);
  --shadow-float: 0 12px 40px rgba(13,38,76,.16), inset 0 1px 0 rgba(255,255,255,.80);

  --radius-pill: 999px;
  --radius-card: 22px;
  --radius-lg:   24px;
  --radius-md:   14px;
  --radius-sm:   11px;

  /* semantic status colors */
  --ok:     #1f8a44;  --ok-bg:     rgba(52,199,89,.16);
  --warn:   #b5670a;  --warn-bg:   rgba(255,159,10,.16);
  --danger: #c0392b;  --danger-bg: rgba(255,59,48,.12);
  --info:   #0e8fc4;  --info-bg:   rgba(14,143,196,.16);

  /* ACCENT : HVAC (default vertical) */
  --accent:    #0a5ae6;
  --accent-2:  #2a7bff;
  --accent-3:  #3a90ff;
  --accent-rgb:10,90,230;
  --bg-1: #cfe0ff;  --bg-2: #d2f4ec;  --bg-3: #e7dcff;

  --app-bg:
    radial-gradient(120% 90%  at 0%   0%,   var(--bg-1) 0%, transparent 50%),
    radial-gradient(110% 90%  at 100% 0%,   var(--bg-2) 0%, transparent 44%),
    radial-gradient(120% 120% at 90%  100%, var(--bg-3) 0%, transparent 50%),
    var(--base);
}

/* ---------- Design tokens : VERTICAL THEMES ---------- */
:root[data-theme="snow"] {
  --accent:#0e8fc4; --accent-2:#27a6dd; --accent-3:#46b6e6; --accent-rgb:14,143,196;
  --bg-1:#cfe9f6; --bg-2:#d4eef4; --bg-3:#dee9f7;
}

:root[data-theme="lawn"] {
  --accent:#2f9e44; --accent-2:#3fb657; --accent-3:#5fce74; --accent-rgb:47,158,68;
  --bg-1:#d8f0d6; --bg-2:#e4f4d8; --bg-3:#ebf3df;
}

:root[data-theme="pool"] {
  --accent:#0d9488; --accent-2:#15b3a4; --accent-3:#34ccbd; --accent-rgb:13,148,136;
  --bg-1:#cfeeea; --bg-2:#d6f1ec; --bg-3:#ddeff2;
}

:root[data-theme="roofing"] {
  --accent:#4f46e5; --accent-2:#6d63f5; --accent-3:#8b82ff; --accent-rgb:79,70,229;
  --bg-1:#dcdaf8; --bg-2:#e6e2fb; --bg-3:#efe6fb;
}

:root[data-theme="pest"] {
  --accent:#7c3aed; --accent-2:#9554f5; --accent-3:#ad74ff; --accent-rgb:124,58,237;
  --bg-1:#e7dcfb; --bg-2:#efe2fb; --bg-3:#f2e1f6;
}

:root[data-theme="health"] {
  --accent:#0b7285; --accent-2:#0f8ba0; --accent-3:#22a5bb; --accent-rgb:11,114,133;
  --bg-1:#cfe8ee; --bg-2:#d9eef0; --bg-3:#e2ecf6;
}

:root[data-theme="beauty"] {
  --accent:#d6336c; --accent-2:#e64980; --accent-3:#f06595; --accent-rgb:214,51,108;
  --bg-1:#fbd9e5; --bg-2:#fde2ec; --bg-3:#f7e3f5;
}

/* ---------- Design tokens : DARK MODE ---------- */
:root[data-mode="dark"] {
  --ink:#eef2f8; --ink-2:#aab6c8; --ink-3:#7f8aa0;
  --surface:#1b2230; --surface-2:#151b29; --base:#0d1320;
  --glass:38,46,64; --hair:255,255,255;
  --glass-border: rgba(255,255,255,.14);
  --shadow-card:  0 8px 28px rgba(0,0,0,.35), inset 0 1px 0 rgba(255,255,255,.06);
  --shadow-float: 0 12px 40px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.08);
  --app-bg:
    radial-gradient(120% 90%  at 0%   0%,   rgba(var(--accent-rgb),.24) 0%, transparent 48%),
    radial-gradient(110% 90%  at 100% 0%,   rgba(var(--accent-rgb),.14) 0%, transparent 46%),
    radial-gradient(120% 120% at 90%  100%, rgba(var(--accent-rgb),.18) 0%, transparent 52%),
    var(--base);
}

/* design source: design-inbox/styles/base.css */
/* base.css — reset, base type, links, keyframes */

/* ============================================================
   Base
   ============================================================ */
* { box-sizing: border-box; }

html, body { margin: 0; }

body {
  font-family: var(--font);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent); text-decoration: none; }

a:hover { color: var(--accent-2); }

button { font-family: inherit; }

@keyframes sheen  { 0%{transform:translateX(-140%)} 55%,100%{transform:translateX(260%)} }

@keyframes ping   { 0%{transform:scale(1);opacity:.6} 70%,100%{transform:scale(2.6);opacity:0} }

@keyframes fadein { from{opacity:0;transform:translateY(8px)} to{opacity:1;transform:none} }

@keyframes pop    { from{opacity:0;transform:scale(.95) translateY(10px)} to{opacity:1;transform:none} }

@keyframes shimmer{ 0%{background-position:-360px 0} 100%{background-position:360px 0} }

@keyframes route-in{ from{opacity:0;transform:translateY(12px)} to{opacity:1;transform:none} }

.route-enter{ animation: route-in .34s cubic-bezier(.2,.7,.2,1) both; }

@keyframes wt-pulse{ 0%{box-shadow:0 0 0 0 rgba(255,159,10,.55)} 70%{box-shadow:0 0 0 14px rgba(255,159,10,0)} 100%{box-shadow:0 0 0 0 rgba(255,159,10,0)} }

@keyframes wt-glow{ 0%,100%{box-shadow:0 0 0 0 rgba(255,159,10,0)} 50%{box-shadow:0 0 0 3px rgba(255,159,10,.20)} }

.wt-pulse{ animation: wt-pulse 2s cubic-bezier(.4,0,.6,1) infinite; }

@keyframes drawer-in { from { transform: translateX(100%); } to { transform: none; } }

/* design source: design-inbox/styles/components.css landing-safe section */
/* components.css — buttons, badges, tabs, cards, panels, states, toast, drawer, dev harness */

/* ============================================================
   ActionButton  — data-module="action-button"
   ============================================================ */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  border: 0; border-radius: var(--radius-pill); cursor: pointer;
  font-weight: 600; font-size: 13px; padding: 9px 16px;
  white-space: nowrap; transition: transform .08s, filter .15s;
}

.btn:active { transform: translateY(1px); }

.btn[disabled] { opacity: .45; cursor: not-allowed; pointer-events: none; }

.btn--primary {
  background: linear-gradient(180deg, var(--accent-2), var(--accent)); color: #fff;
  box-shadow: 0 4px 12px rgba(var(--accent-rgb), .35), inset 0 1px 0 rgba(255,255,255,.4);
}

.btn--primary:hover { filter: brightness(1.05); }

.btn--ghost {
  background: rgba(var(--glass), .7); border: 1px solid var(--glass-border); color: var(--ink);
}

.btn--danger {
  background: rgba(255,59,48,.08); border: 1px solid rgba(255,59,48,.22); color: var(--danger);
}

.btn--info { background: linear-gradient(180deg, var(--accent-3), var(--accent)); color: #fff; }

.btn--onaccent { background: var(--surface); color: var(--accent); }

.btn--onaccent:hover { filter: brightness(.98); }

.btn--glass-hero { background: rgba(255,255,255,.18); border: 1px solid rgba(255,255,255,.35); color: #fff; }

.btn--glass-hero:hover { background: rgba(255,255,255,.26); }

.btn--block { display: flex; width: 100%; }

.btn--lg { padding: 11px 20px; font-weight: 700; }

/* ============================================================
   PageHeader  — data-module="page-header"
   ============================================================ */
.page-header { display: flex; align-items: flex-end; gap: 14px; margin: 8px 4px 18px; }

.page-header__title { font-weight: 800; font-size: 28px; line-height: 1.18; letter-spacing: -.025em; margin: 0; padding-top: 2px; }

.page-header__sub  { font-size: 14.5px; color: var(--ink-2); margin-top: 3px; }

/* ============================================================
   StatusBadge  — data-module="status-badge"
   ============================================================ */
.status-badge {
  display: inline-flex; align-items: center; gap: 6px;
  border-radius: var(--radius-pill); padding: 5px 12px;
  font-weight: 600; font-size: 12px; white-space: nowrap;
}

.status-badge--ok       { background: var(--ok-bg);     color: var(--ok); }

.status-badge--progress { background: rgba(255,159,10,.20); color: var(--warn); }

.status-badge--scheduled{ background: rgba(120,120,128,.18); color: var(--ink-3); }

.status-badge--warn     { background: var(--warn-bg);   color: var(--warn); }

.status-badge--danger   { background: var(--danger-bg); color: var(--danger); }

.status-badge--info     { background: var(--info-bg);   color: var(--info); }

/* ============================================================
   Tabs / SegmentedControl  — data-module="tabs"
   ============================================================ */
.tabs { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; }

.tab {
  background: rgba(var(--glass), .6); border: 1px solid var(--glass-border);
  border-radius: var(--radius-pill); padding: 6px 13px;
  font-weight: 530; font-size: 12.5px; color: var(--ink-2);
  cursor: pointer; white-space: nowrap; user-select: none;
}

.tab:hover { color: var(--ink); }

.tab--active { background: #1d1d1f; color: #fff; font-weight: 590; border-color: transparent; }

:root[data-mode="dark"] .tab--active { background: #fff; color: #10151f; }

.select-pill {
  background: rgba(var(--glass), .6); border: 1px solid var(--glass-border);
  border-radius: var(--radius-pill); padding: 6px 10px;
  font-weight: 530; font-size: 12.5px; color: var(--ink-2); cursor: pointer;
}

/* Card shell — data-module="glass-card" */
.card {
  background: rgba(var(--glass), .5);
  backdrop-filter: var(--glass-blur); -webkit-backdrop-filter: var(--glass-blur);
  border: 1px solid var(--glass-border); border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
}

.card__head { display: flex; align-items: center; gap: 10px; padding: 12px 12px 10px; flex-wrap: wrap; }

.card__title { font-weight: 700; font-size: 16px; }

.card--pad { padding: 18px; }

/* ============================================================
   States : loading / empty / error  — data-module respectively
   ============================================================ */
.skeleton {
  background: linear-gradient(90deg, rgba(var(--hair),.06) 25%, rgba(var(--hair),.12) 37%, rgba(var(--hair),.06) 63%);
  background-size: 720px 100%; animation: shimmer 1.4s ease-in-out infinite; border-radius: 8px;
}

.state-block {
  display: flex; flex-direction: column; align-items: center; text-align: center;
  gap: 10px; padding: 54px 24px; animation: fadein .3s ease;
}

.state-block__glyph {
  width: 60px; height: 60px; border-radius: 18px; display: grid; place-items: center;
  font-size: 26px; background: rgba(var(--glass), .6); border: 1px solid var(--glass-border);
}

.state-block__glyph--error { background: var(--danger-bg); }

.state-block__title { font-weight: 700; font-size: 17px; }

.state-block__desc { font-size: 13.5px; color: var(--ink-2); max-width: 340px; }

/* ============================================================
   Toast  — data-module="toast"
   ============================================================ */
.toast {
  position: fixed; left: 50%; bottom: 26px; transform: translateX(-50%);
  z-index: 300; display: flex; align-items: center; gap: 10px;
  background: #10151f; color: #fff; border-radius: var(--radius-pill);
  padding: 12px 20px; font-weight: 600; font-size: 13.5px;
  box-shadow: 0 12px 34px rgba(0,0,0,.28); animation: pop .28s ease;
}

.toast__dot { width: 8px; height: 8px; border-radius: var(--radius-pill); background: #34c759; }

/* ============================================================
   Drawer / Modal  — data-module="drawer" / "modal"
   ============================================================ */
.scrim { position: fixed; inset: 0; z-index: 250; background: rgba(10,16,28,.42); backdrop-filter: blur(3px); animation: fadein .2s ease; }

.drawer {
  position: fixed; top: 0; right: 0; bottom: 0; z-index: 260; width: min(440px, 92vw);
  background: var(--surface); box-shadow: -20px 0 60px rgba(0,0,0,.28);
  padding: 22px; overflow-y: auto; animation: drawer-in .28s cubic-bezier(.2,.8,.2,1);
}

.drawer__head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 18px; }

.drawer__title { font-weight: 800; font-size: 20px; letter-spacing: -.02em; }

.drawer__close { width: 34px; height: 34px; border-radius: var(--radius-pill); background: var(--surface-2); border: 0; cursor: pointer; font-size: 16px; }

/* ============================================================
   Dev harness  — data-dev-toolbar  (PREVIEW ONLY — Codex strips this)
   ============================================================ */
.dev-toolbar {
  position: fixed; left: 50%; bottom: 12px; transform: translateX(-50%);
  z-index: 400; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; justify-content: center;
  background: rgba(16,21,31,.9); backdrop-filter: blur(14px); color: #cfd6e4;
  border: 1px solid rgba(255,255,255,.1); border-radius: 14px;
  padding: 8px 10px; font: 500 11.5px var(--font); max-width: 96vw;
}

.dev-toolbar select, .dev-toolbar button {
  background: rgba(255,255,255,.08); color: #eef2f8; border: 1px solid rgba(255,255,255,.12);
  border-radius: 8px; padding: 5px 8px; font: 500 11.5px var(--font); cursor: pointer;
}

.dev-toolbar__group { display: flex; align-items: center; gap: 4px; }

.dev-toolbar__label { color: #79839a; text-transform: uppercase; letter-spacing: .06em; font-size: 9.5px; }

.dev-toolbar button.is-on { background: var(--accent); border-color: transparent; color: #fff; }

/* Viewport simulation frame (preview harness) */
.viewport-host { display: flex; justify-content: center; }

.viewport-frame { width: 100%; transition: max-width .2s ease; }

.viewport-frame[data-vw="390"]  { max-width: 390px; }

.viewport-frame[data-vw="768"]  { max-width: 768px; }

/* Wave 14.1 — wide presets are TRUE-width: an explicit width (not just max-width)
   so a narrower preview pane never clamps the layout; the host scrolls instead. */
.viewport-frame[data-vw="1180"] { width: 1180px; min-width: 1180px; max-width: 1180px; }

.viewport-frame[data-vw="1440"] { width: 1440px; min-width: 1440px; max-width: 1440px; background: var(--base); }

.viewport-host:has(.viewport-frame[data-vw="1180"]), .viewport-host:has(.viewport-frame[data-vw="1440"]) { justify-content: flex-start; overflow-x: auto; }

.viewport-frame:not([data-vw="1440"]):not([data-vw="full"]) {
  margin: 14px auto; box-shadow: 0 20px 60px rgba(13,38,76,.18); border-radius: 20px; overflow: hidden; background: var(--base);
}

/* Panel — frosted section card used across detail */
.panel {
  background: rgba(var(--glass), .55);
  backdrop-filter: var(--glass-blur); -webkit-backdrop-filter: var(--glass-blur);
  border: 1px solid var(--glass-border); border-radius: 20px;
  box-shadow: 0 8px 28px rgba(13,38,76,.10); padding: 20px;
}

.panel__title { font-weight: 700; font-size: 15px; }

.chip { background: rgba(var(--glass), .6); border: 1px solid var(--glass-border); border-radius: var(--radius-pill); padding: 6px 12px; font-weight: 590; font-size: 12px; color: var(--ink-2); cursor: pointer; white-space: nowrap; }

/* design source: design-inbox/styles/shell.css landing-safe section */
/* shell.css — app-shell, page layout, top-nav */

/* ============================================================
   AppShell  — data-module="app-shell"
   ============================================================ */
.app-shell {
  min-height: 100vh;
  background: var(--app-bg);
  background-attachment: fixed;
}

.page {
  max-width: 1120px;
  margin: 0 auto;
  padding: 22px 22px 60px;
}

.page--narrow { max-width: 880px; }

/* frosted surface primitive */
.glass {
  background: rgba(var(--glass), .55);
  backdrop-filter: var(--glass-blur);
  -webkit-backdrop-filter: var(--glass-blur);
  border: 1px solid var(--glass-border);
  box-shadow: var(--shadow-card);
}

/* ============================================================
   TopNav  — data-module="top-nav"
   ============================================================ */
.top-nav-wrap { position: sticky; top: 0; z-index: 120; padding: 16px 22px 8px; }

.top-nav {
  max-width: 1120px; margin: 0 auto; position: relative;
  display: flex; align-items: center; gap: 16px;
  background: rgba(var(--glass), .55);
  backdrop-filter: var(--glass-blur); -webkit-backdrop-filter: var(--glass-blur);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-pill);
  padding: 9px 14px;
  box-shadow: 0 8px 26px rgba(13,38,76,.10), inset 0 1px 0 rgba(255,255,255,.75);
}

.top-nav__brand { display: flex; align-items: center; gap: 9px; cursor: pointer; flex-shrink: 0; }

.brand-logo {
  width: 30px; height: 30px; border-radius: 9px;
  background: linear-gradient(160deg, var(--accent-3), var(--accent));
  display: grid; place-items: center;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.5);
  flex-shrink: 0;
}

.brand-logo::after {
  content: ""; width: 11px; height: 11px;
  background: var(--surface); border-radius: 3px; transform: rotate(45deg);
}

.brand-logo--lg { width: 46px; height: 46px; border-radius: 13px; box-shadow: 0 4px 12px rgba(var(--accent-rgb),.3); }

.brand-logo--lg::after { width: 16px; height: 16px; border-radius: 4px; }

.brand-name { font-weight: 700; font-size: 17px; letter-spacing: -.01em; white-space: nowrap; }

.nav-links { display: flex; gap: 2px; margin-left: 6px; min-width: 0; overflow: hidden; position: relative; }

.nav-pill {
  position: absolute; top: 0; bottom: 0; left: 0; width: 0;
  border-radius: var(--radius-pill); background: rgba(var(--glass), .9);
  box-shadow: 0 1px 4px rgba(var(--hair), .1); pointer-events: none; z-index: 0;
  transition: transform .32s cubic-bezier(.5,.05,.2,1.05), width .32s cubic-bezier(.5,.05,.2,1.05), opacity .2s;
}

.nav-link {
  padding: 8px 15px; font-weight: 530; font-size: 13.5px;
  color: var(--ink-2); cursor: pointer; border-radius: var(--radius-pill);
  white-space: nowrap; user-select: none; position: relative; z-index: 1; transition: color .2s;
}

.nav-link:hover { color: var(--ink); }

.nav-link--active { font-weight: 600; color: var(--ink); }

.top-nav__actions { margin-left: auto; display: flex; align-items: center; gap: 10px; flex-shrink: 0; }

.theme-picker {
  display: flex; align-items: center; gap: 8px;
  background: rgba(var(--glass), .55); border: 1px solid var(--glass-border);
  border-radius: var(--radius-pill); padding: 7px 12px;
}

.theme-swatch {
  width: 16px; height: 16px; border-radius: var(--radius-pill); cursor: pointer;
  transition: transform .12s; box-shadow: 0 0 0 1px rgba(var(--hair), .12); opacity: .55;
}

.theme-swatch:hover { transform: scale(1.15); opacity: 1; }

.theme-swatch--active { opacity: 1; box-shadow: 0 0 0 2px var(--surface), 0 0 0 4px currentColor; }

.icon-btn {
  position: relative; width: 34px; height: 34px; border-radius: var(--radius-pill);
  background: rgba(var(--glass), .65); border: 1px solid var(--glass-border);
  display: grid; place-items: center; font-size: 15px; cursor: pointer;
}

.icon-btn:hover { background: rgba(var(--glass), .95); }

.avatar {
  width: 34px; height: 34px; border-radius: var(--radius-pill);
  background: linear-gradient(160deg, #ffd27a, #ff9b6a);
  border: 1px solid var(--glass-border); cursor: pointer; flex-shrink: 0;
}

.dot-badge {
  position: absolute; top: 5px; right: 6px; width: 7px; height: 7px;
  border-radius: var(--radius-pill); background: #ff3b30; border: 1.5px solid var(--surface);
}

.cart-badge {
  position: absolute; top: -4px; right: -4px; min-width: 18px; height: 18px; padding: 0 4px;
  border-radius: var(--radius-pill); background: var(--accent); color: #fff;
  font-weight: 700; font-size: 11px; display: grid; place-items: center; border: 1.5px solid var(--surface);
}

.hamburger { display: none; }

/* collapsed nav popover — data-state="mobile-navigation-open" */
.mobile-nav {
  position: absolute; top: calc(100% + 10px); right: 8px; z-index: 130;
  display: flex; flex-direction: column; gap: 2px;
  width: 220px; max-width: calc(100vw - 44px);
  background: var(--surface); border: 1px solid var(--glass-border);
  border-radius: 18px; box-shadow: 0 18px 44px rgba(13,38,76,.20);
  padding: 8px; animation: pop .18s ease;
}

.mobile-nav .nav-link { display: block; padding: 11px 14px; border-radius: 12px; font-size: 14.5px; }

.mobile-nav .nav-link--active { background: rgba(var(--glass), .9); }

:root[data-mode="dark"] .mobile-nav .nav-link--active { background: rgba(var(--glass), 1); }

.avatar-stack { display: flex; }

.avatar-stack__a { width: 32px; height: 32px; border-radius: 999px; border: 2px solid #143a8c; }

.avatar-stack__a + .avatar-stack__a { margin-left: -9px; }

/* design source: design-inbox/styles/seo.css shared scaffolding */
/* seo.css — public SEO landing sections (route: seo.landing)
   One reusable section set for all six verticals; colors derive
   from tokens.css (data-theme). Responsive follows the container
   convention: .vw-mobile / .vw-tablet classes on .app-shell. */

.seo-page { display: flex; flex-direction: column; gap: 26px; padding-bottom: 0; }

/* ---------- shared section scaffolding ---------- */
