.seo-footer__grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.seo-footer__col { display: flex; flex-direction: column; gap: 7px; font-size: 13px; color: var(--ink-2); }
.seo-footer__head { font-size: 10.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .08em; color: var(--ink-3); margin-bottom: 3px; }
.seo-footer__row { display: flex; justify-content: space-between; gap: 14px; max-width: 220px; }
